    (title.match(/\(([^)]+)\)/g) || []).forEach((p) => { const k = p.slice(1, -1).trim(); if (/^[A-Z0-9][A-Za-z0-9 .+-]{1,19}$/.test(k) && /[A-Z]{2}/.test(k)) keys.push(k); });
