      versions: { dataset: refs.dataset_version || '', corpus: refs.corpus_version || '', prompt: refs.prompt_version || '', rules: refs.rules_version || '' },
      hashes,
    };
    payload.report_hash = sha256Hex(canonicalJSON(payload));
    return payload;
  }
