    const reqName = Object.fromEntries(p.decisions.map((d) => [d.requirement_id, d.element_name]));
    let h = '<!DOCTYPE html><html lang="th"><head><meta charset="utf-8"><title>รายงานผลวิเคราะห์ ' + e(p.run_id) + '</title>'
