      n_certs: planItems.filter((p) => p.type === 'certification').length,
      cost_usd: planItems.reduce((s, p) => s + (p.cost_usd || 0), 0),
      covered_gap_weight: round([...covered].reduce((s, r) => s + w[r], 0), 6), gap_weight: round(gaps.reduce((s, r) => s + w[r], 0), 6),
      notice,
    },
  },
}];

