  return [{ json: { ok: false, http_status: 502, errors: ['อัปโหลดขึ้น Google Drive ไม่สำเร็จ: ' + msg.slice(0, 200) + ' — ตรวจ credential "Google Drive OAuth2" และ Folder ID ในโหนด Upload PDF to Drive'] } }];
